-- =====================================================================
-- identity-service · database: identity_db · Flyway V1__init.sql
-- Owns: authentication principals, credentials, federation, MFA,
--       sessions and refresh-token lineage (reuse detection).
-- Spring Authorization Server tables (oauth2_registered_client,
-- oauth2_authorization, oauth2_authorization_consent) are created in
-- V2__spring_authorization_server.sql from the DDL shipped with SAS.
-- PostgreSQL 16+. IDs are UUIDv7 generated by the application.
-- =====================================================================
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE user_accounts (
    id                 uuid         PRIMARY KEY,
    email              citext       NOT NULL UNIQUE,
    email_verified_at  timestamptz,
    user_type          varchar(16)  NOT NULL
                       CHECK (user_type IN ('PATIENT','DOCTOR','ADMIN')),
    status             varchar(24)  NOT NULL DEFAULT 'PENDING_VERIFICATION'
                       CHECK (status IN ('PENDING_VERIFICATION','ACTIVE','SUSPENDED','LOCKED','DEACTIVATED')),
    mfa_required       boolean      NOT NULL DEFAULT false,   -- forced true for DOCTOR/ADMIN
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    deactivated_at     timestamptz,
    version            bigint       NOT NULL DEFAULT 0
);

CREATE TABLE credentials (
    user_id              uuid         PRIMARY KEY REFERENCES user_accounts(id) ON DELETE CASCADE,
    password_hash        varchar(255) NOT NULL,              -- Argon2id PHC string
    password_changed_at  timestamptz  NOT NULL DEFAULT now(),
    must_change          boolean      NOT NULL DEFAULT false,
    failed_attempts      integer      NOT NULL DEFAULT 0,
    locked_until         timestamptz
);

CREATE TABLE password_history (
    user_id        uuid         NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,
    password_hash  varchar(255) NOT NULL,
    created_at     timestamptz  NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, created_at)
);

CREATE TABLE federated_identities (
    id                uuid         PRIMARY KEY,
    user_id           uuid         NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,
    provider          varchar(32)  NOT NULL CHECK (provider IN ('GOOGLE','APPLE','MICROSOFT_ENTRA')),
    provider_subject  varchar(255) NOT NULL,
    email_at_link     citext,
    linked_at         timestamptz  NOT NULL DEFAULT now(),
    last_login_at     timestamptz,
    UNIQUE (provider, provider_subject)
);
CREATE INDEX ix_federated_user ON federated_identities(user_id);

CREATE TABLE mfa_factors (
    id                      uuid        PRIMARY KEY,
    user_id                 uuid        NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,
    factor_type             varchar(16) NOT NULL CHECK (factor_type IN ('TOTP','WEBAUTHN','SMS')),
    label                   varchar(64),
    status                  varchar(16) NOT NULL DEFAULT 'PENDING'
                            CHECK (status IN ('PENDING','ACTIVE','DISABLED')),
    totp_secret_enc         bytea,          -- AES-256-GCM, DEK wrapped by Key Vault KEK
    webauthn_credential_id  bytea UNIQUE,
    webauthn_public_key     bytea,          -- COSE-encoded
    webauthn_sign_count     bigint,
    webauthn_aaguid         uuid,
    webauthn_transports     text[],
    phone_enc               bytea,
    created_at              timestamptz NOT NULL DEFAULT now(),
    verified_at             timestamptz,
    last_used_at            timestamptz,
    CONSTRAINT chk_factor_material CHECK (
        (factor_type = 'TOTP'     AND totp_secret_enc IS NOT NULL) OR
        (factor_type = 'WEBAUTHN' AND webauthn_credential_id IS NOT NULL AND webauthn_public_key IS NOT NULL) OR
        (factor_type = 'SMS'      AND phone_enc IS NOT NULL))
);
CREATE INDEX ix_mfa_user_active ON mfa_factors(user_id) WHERE status = 'ACTIVE';

CREATE TABLE mfa_recovery_codes (
    id          uuid         PRIMARY KEY,
    user_id     uuid         NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,
    code_hash   varchar(255) NOT NULL,      -- Argon2id
    created_at  timestamptz  NOT NULL DEFAULT now(),
    used_at     timestamptz
);
CREATE INDEX ix_recovery_user_unused ON mfa_recovery_codes(user_id) WHERE used_at IS NULL;

-- Short-lived MFA challenges / OTPs live in Redis (TTL 5 min), not here.

CREATE TABLE sessions (
    id               uuid         PRIMARY KEY,                 -- emitted as JWT "sid"
    user_id          uuid         NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,
    client_id        varchar(100) NOT NULL,
    device_id        varchar(128),
    device_name      varchar(128),
    platform         varchar(16)  CHECK (platform IN ('IOS','ANDROID','WEB')),
    ip_address       inet,
    user_agent       varchar(512),
    auth_methods     text[]       NOT NULL,                    -- amr: pwd, otp, hwk, fed, sms
    assurance_level  smallint     NOT NULL DEFAULT 1
                     CHECK (assurance_level BETWEEN 1 AND 3),  -- AAL1/2/3
    created_at       timestamptz  NOT NULL DEFAULT now(),
    last_seen_at     timestamptz  NOT NULL DEFAULT now(),
    expires_at       timestamptz  NOT NULL,                    -- absolute lifetime
    revoked_at       timestamptz,
    revoke_reason    varchar(64)
);
CREATE INDEX ix_sessions_user_active ON sessions(user_id) WHERE revoked_at IS NULL;

-- Rotating refresh tokens. Presenting a token whose used_at IS NOT NULL
-- is a replay => revoke the whole session (token family).
CREATE TABLE refresh_token_lineage (
    id          uuid        PRIMARY KEY,
    session_id  uuid        NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    token_hash  bytea       NOT NULL UNIQUE,                   -- SHA-256 of opaque token
    parent_id   uuid        REFERENCES refresh_token_lineage(id),
    issued_at   timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz NOT NULL,
    used_at     timestamptz,
    revoked_at  timestamptz
);
CREATE INDEX ix_rtl_session ON refresh_token_lineage(session_id);

CREATE TABLE outbox_events (
    id              uuid         PRIMARY KEY,
    aggregate_type  varchar(64)  NOT NULL,
    aggregate_id    uuid         NOT NULL,
    event_type      varchar(128) NOT NULL,
    topic           varchar(128) NOT NULL,
    payload         jsonb        NOT NULL,
    headers         jsonb        NOT NULL DEFAULT '{}',
    created_at      timestamptz  NOT NULL DEFAULT now(),
    published_at    timestamptz
);
CREATE INDEX ix_outbox_unpublished ON outbox_events(created_at) WHERE published_at IS NULL;
